    public static IReadOnlyCollection<string> Keys => Values.Keys;
    public static bool ContainsKey(string key) => Values.ContainsKey(key);
    public static bool TryTranslate(string locale, string key, out string text)
    {
        if (Values.TryGetValue(key, out var row))
        {
            text = row[locale switch { "es" => 0, "fr" => 2, "it" => 3, _ => 1 }];
            return true;
        }
        text = ""; return false;
    }
